/*
 * A209562  Triangle of coefficients of polynomials v(n,x) jointly generated
 *          with A209561; see the Formula section.
 * https://oeis.org/A209562
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   a(n) is the flattened column of the triangle of coefficients *
 *            of the polynomials v(n,x) generated by * u(1,x)=1, v(1,x)=1 *
 *            u(n,x)=x*u(n-1,x)+v(n-1,x) * v(n,x)=x*u(n-1,x)+v(n-1,x)+1 * The
 *            sequence lists the coefficients of v(n,x) from the constant term
 *            * up to the leading term, row by row. For a...
 * Range:     u8 n <= 59, u16 n <= 72, u32 n <= 72, u64 n <= 72, u128 n <= 72,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n) {
    /* Find the row r such that r(r+1)/2 >= n. */
    idx_t r = 1;
    idx_t cum = 1;          /* cum = r(r+1)/2 for current r */
    while (cum < n) {
        ++r;
        cum += r;
    }
    /* Compute index within the row (0‑based). */
    idx_t prev_cum = cum - r;            /* sum of terms before row r */
    idx_t offset = n - prev_cum - 1;     /* position within row r */

    /* Allocate arrays for u and v of the current row. */
    size_t cur_len = 1;
    seq_t *u = (seq_t *)malloc(sizeof(seq_t) * cur_len);
    seq_t *v = (seq_t *)malloc(sizeof(seq_t) * cur_len);
    if (!u || !v) { /* allocation failure – return 0 as a sentinel */
        free(u); free(v);
        return 0;
    }
    u[0] = 1;      /* u(1,x) = 1 */
    v[0] = 1;      /* v(1,x) = 1 */

    if (r == 1) {
        seq_t res = v[0];
        free(u); free(v);
        return res;
    }

    /* Iterate from row 2 up to row r. */
    for (idx_t row = 2; row <= r; ++row) {
        size_t new_len = cur_len + 1;
        seq_t *u_new = (seq_t *)malloc(sizeof(seq_t) * new_len);
        seq_t *v_new = (seq_t *)malloc(sizeof(seq_t) * new_len);
        if (!u_new || !v_new) {
            free(u); free(v);
            free(u_new); free(v_new);
            return 0;
        }

        for (size_t k = 0; k < new_len; ++k) {
            seq_t shift = (k > 0) ? u[k - 1] : (seq_t)0;                 /* x*u(prev)[k] */
            seq_t v_val = (k < cur_len) ? v[k] : (seq_t)0;              /* v(prev)[k] */
            u_new[k] = shift + v_val;                                   /* u(row)[k] */
            v_new[k] = shift + v_val + ((k == 0) ? (seq_t)1 : (seq_t)0); /* v(row)[k] + 1 if constant term */
        }

        free(u); free(v);
        u = u_new;
        v = v_new;
        cur_len = new_len;
    }

    /* Extract the requested coefficient. */
    seq_t result = v[offset];

    /* Clean up. */
    free(u); free(v);
    return result;
}
